//! Vendored WebP files for `clazel-webp` (phase-6.md item 6.8): Wuffs'
//! `test/data/*.webp` (the lossless ones, the animated one, and two small
//! lossy ones for the refusal test).
//!
//! The files are binary, so there is nothing to translate: like the GIF
//! converter (`wuffs_gif.rs`), this checks that each file is the one its
//! `SOURCE.md` names (a `` - `X.webp`: sha256 `…` `` line) and that it still
//! looks like a WebP (`RIFF`, four size bytes, `WEBP`), and writes a table
//! that embeds it with `include_bytes!`. No chunk is parsed here: that is the
//! crate's job, and the differential test's.

use std::fmt::Write as _;
use std::path::Path;

use sha2::{Digest, Sha256};

use super::fonts::listed_hash;
use super::hash::to_hex;

/// `tests/data/wuffs-webp/`: Wuffs' `test/data/*.webp` that item 6.8 uses.
pub const FILES: &[&str] = &[
    "animated-red-blue.webp",
    "bricks-color.lossless.webp",
    "bricks-dither.lossless.webp",
    "bricks-gray.lossless.webp",
    "bricks-nodither.lossless.webp",
    "harvesters.lossless.webp",
    "hat.lossless.webp",
    "hibiscus.primitive.lossless.webp",
    "hibiscus.regular.lossless.webp",
    "hippopotamus.lossless.webp",
    "mona-lisa.21x32.lossless.webp",
    "mona-lisa.21x32.q0.lossy.webp",
    "pjw-thumbnail.lossless.webp",
    "pjw-thumbnail.lossy.webp",
];

/// Check the suite in `dir` and write its table.
pub fn convert(dir: &Path) -> Result<String, String> {
    let name = dir
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| format!("{}: no directory name", dir.display()))?;
    if name != "wuffs-webp" {
        return Err(format!("no WebP list for suite {name:?}"));
    }
    let source =
        std::fs::read_to_string(dir.join("SOURCE.md")).map_err(|e| format!("SOURCE.md: {e}"))?;
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo xtask testdata` from `tests/data/{name}/` \
         (xtask/src/testdata/wuffs_webp.rs). Do not edit.\n\
         \n\
         /// One vendored WebP file, checked against `SOURCE.md` when generated.\n\
         pub struct Case {{\n    \
             /// The file's name in `tests/data/{name}/`.\n    \
             pub file: &'static str,\n    \
             /// Its SHA-256, as `SOURCE.md` lists it.\n    \
             pub sha256: &'static str,\n    \
             /// Its bytes.\n    \
             pub bytes: &'static [u8],\n\
         }}\n\
         \n\
         /// Every file of the suite.\n\
         pub const FILES: &[Case] = &["
    );
    for file in FILES {
        let bytes = std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))?;
        let hash = to_hex(&Sha256::digest(&bytes));
        let listed = listed_hash(&source, file)?;
        if hash != listed {
            return Err(format!(
                "{file}: SHA-256 {hash} differs from SOURCE.md's {listed}"
            ));
        }
        let riff = bytes.get(..4) == Some(b"RIFF") && bytes.get(8..12) == Some(b"WEBP");
        if !riff {
            return Err(format!("{file}: does not start with `RIFF`, size, `WEBP`"));
        }
        let _ = writeln!(
            out,
            "    Case {{\n        \
                 file: {file:?},\n        \
                 sha256: {hash:?},\n        \
                 bytes: include_bytes!(\"../data/{name}/{file}\"),\n    \
             }},"
        );
    }
    out.push_str("];\n");
    Ok(out)
}
